from pathlib import Path
import json,sys
sys.path.insert(0,'skills/evidence-to-proof-review/scripts')
import corpus
p=Path('tmp/06-procurement-contract-correct')
r=json.loads((p/'input/report-ledger.json').read_text())
paths={'P':'procurement-standard.docx.md','V':'revision-amendment.pdf.md','A':'approval-attestations.scan.pdf.md','D':'delegation-notice.md','X':'exception-file.md','L':'purchase-register.md','F':'reconciliation-correspondence.md'}
def ev(mark):
 prefix=mark[0]; n=int(mark[1:]); path='input/sources/'+paths[prefix]
 anchor=f'docx-p-{2*n+2:04}' if prefix=='P' else f'pdf-page-{n+1:04}'+('-reviewed-0001' if prefix=='A' else '') if prefix in 'VA' else mark
 s=corpus.passage(p,path,anchor)
 return {'path':path,'anchor':anchor,'quote':s['quote']}
A=['The supplied synthetic records and operative clauses are faithfully transcribed; source authenticity and external procurement law are outside the audit.','Use exact euro cents after prescribed single rounding and exact UTC minute timestamps. Named source coverage, not general document omission, governs negative event facts.']
L=['The conclusion is limited to the named synthetic requirement, operative rule and May-June 2029 coverage; it does not authenticate real-world events.']
findings=[]
def add(n,components,q,markers,rules,steps,name,target,formal='proved',limits=None,recommendation='Retain the qualified finding and its precise source references.'):
 ident=f'C06-C{n:02}'
 f={'claim_id':ident,'report_quote':r[ident],'report_anchor':ident,'component_propositions':components,'question':q,'evidence':[ev(m) for m in markers.split()], 'rules':rules,'assumptions':A,'reasoning':[f'{i+1}. {step}' for i,step in enumerate(steps)],'semantic_state':'supported','argument_status':'sufficient','formal_status':formal,'proofs':[{'module':'Audit','theorem':'Audit.'+name,'relation':'auxiliary' if formal=='auxiliary' else 'supports','target':target}] if name else [],'limits':limits or L,'recommendation':recommendation}
 findings.append(f)
add(1,['Same known requirement aggregates','Combined value EUR 25000','Revision 2 competition required absent exception','Complete coverage records neither competition nor exception'], 'Do P-11/P-12 meet every aggregation condition and lack the required competition or exception?', 'P02 P03 V01 L01 L02 F04', ['P03 aggregates same project, same legal supplier and one operational requirement within thirty inclusive dates when fully known before first commitment.','P02 applies the inclusive revision-2 EUR 25000 threshold; L01 closes competition/exception events for these orders.'], ['L02 identifies TIDE-4, Pelican Instruments Ltd and two halves of one installation; F04 confirms that different pallets and labels do not create independent requirements.','Both prices and the full specification were known May 28, before June 3. June 20 minus June 3 is 17 dates, within the 29-date offset limit.','Receipt June 1 09:00 selects revision 2. 12400+12600=25000 exactly, meeting its inclusive threshold.','L02 explicitly records competition certificate, emergency declaration and other exception determination as none under L01 completeness. Director spending approvals do not supply competition.'],'rackObligation','Audit.rackAggregates = true ∧ Audit.rackTotal = 2500000 ∧ Audit.threshold (Audit.revisionAt 540) ≤ Audit.rackTotal ∧ Audit.competitionSatisfied 2 Audit.rackTotal false false = false')
add(2,['Combined normalized EUR 25000'], 'Is the combined normalized value exactly EUR 25000?', 'P04 L01 L02', ['Use supplied already-normalized values exactly once; no further component rounding or VAT adjustment.'], ['L01 explains normalized values already include charges and final rounding; L02 gives 1240000 and 1260000 cents.','Their exact sum is 2500000 cents, or EUR 25000.00.','No supplied adjustment contradicts those normalized entries.'],'rackSum','Audit.rackTotal = 2500000')
add(3,['Exact FX conversion and once-only rounding','Threshold reached','Completed competition recorded'], 'Does P-13 normalize to the threshold, and is timely completed competition recorded?', 'P02 P04 V01 V05 L01 L03 F01', ['P04 requires exact rational conversion at contractual rate, then nearest-cent rounding with ties upward. Threshold applies after rounding.','P02 treats a complete competition certificate as attesting prescribed competition before commitment.'], ['V05 supplies exact USD 27777.775 and 0.9 EUR/USD, with no extra charges, rebates or VAT adjustments.','27777775/1000 ×9/10 =249999975/10000 EUR =24999.9975 EUR; its cent value 2499999.75 rounds to 2500000 cents.','Receipt June 4 selects revision 2 and the rounded value equals its inclusive EUR25000 threshold.','L03 records a complete three-supplier certificate June10 before June12 commitment, corroborating competition; F01 independently agrees with the arithmetic.'],'p13Normalization','Audit.p13Num = 249999975 ∧ Audit.p13Den = 10000 ∧ Audit.p13Cents = 2500000 ∧ Audit.threshold 2 ≤ Audit.p13Cents ∧ (9 : Nat) < 11 ∧ Audit.competitionSatisfied 2 Audit.p13Cents true false = true')
add(4,['Unrounded EUR24999.9975','Unrounded threshold test is wrong calculation stage'], 'Is the stated intermediate value exact, and would testing it before cent rounding misapply P04?', 'P02 P04 V05 F01', ['P04 explicitly forbids threshold testing against the unrounded conversion; use normalized cents.'], ['The exact conversion is 249999975/10000 EUR, or EUR24999.9975.','That rational amount is less than EUR25000, but its rounded normalized amount is exactly EUR25000.','The Lean result checks both comparisons. Their divergence identifies why the early threshold test is invalid; F01 expressly warns against it.'],'p13Intermediate','Audit.p13Num = 249999975 ∧ Audit.p13Den = 10000 ∧ Audit.p13Num < 25000 * Audit.p13Den ∧ ¬ Audit.p13Cents < Audit.threshold 2')
add(5,['P14 rounds to EUR24999.99','Independent requirement remains below revision2 threshold'], 'Does P-14 round down to EUR24999.99 and remain below its applicable threshold without aggregation?', 'P02 P03 P04 V01 L03 F02', ['Apply final nearest-cent rounding, not truncation as a general rule; no aggregation exists according to L03/F02.'], ['P14 exact EUR24999.994 gives 2499999.4 cents; .4 is below the .5 upward-rounding boundary.','The prescribed result is 2499999 cents. June5 receipt selects revision2, whose 2500000-cent threshold is greater by one cent.','L03 and F02 explicitly rule out another aggregating purchase. Lack of competition therefore does not breach P02 here; approval remains a separate requirement.'],'p14Normalization','Audit.roundCents 24999994 1000 = 2499999 ∧ Audit.roundCents 24999994 1000 < Audit.threshold 2')
add(6,['P15 category/value within delegation','Approval at inclusive expiry valid','Approval strictly precedes commitment'], 'Was Dana authorized when approving P15 at 17:00, notwithstanding the 17:01 commitment?', 'P05 D01 D02 D03 L04', ['P05 measures authority at approval, requires strictly pre-commitment approval, and does not invalidate it merely because commitment follows expiry.','D01 covers consumables ≤EUR15000 through June15 17:00 inclusive; D02 has no amendments.'], ['P15 is consumables worth EUR14900, inside Dana category and inclusive monetary ceiling.','The exact approval at June15 17:00 equals, rather than exceeds, the stated expiry. D03 expressly includes that minute.','Commitment at17:01 is strictly later, so all stated authority and chronology requirements hold. The Lean predicate checks category, value, expiry and ordering.'],'p15Approval','Audit.validDana true 1490000 Audit.expiry (Audit.expiry + 1)')
add(7,['P16 value meets ceiling','Dana approval expired','No alternative approval in complete coverage','No valid precommitment approval'], 'Does P16 fail approval validity despite satisfying the monetary ceiling?', 'P05 D01 D02 D03 D04 L01 L04', ['Value, category, time and precommitment order are conjunctive conditions; satisfying a monetary ceiling cannot cure expired authority.','L01/L04 close alternative approvals for P16; D02 closes delegation extensions.'], ['EUR15000 exactly meets the value ceiling and consumables is in scope.','June15 17:01 approval exceeds the last authorized minute17:00; no grace period or earlier click may be invented.','The17:10 commitment is later, but that does not repair expired authority at17:01.','L04 expressly excludes any director or alternate approval in the complete period, so the only recorded approval is invalid and no valid approval exists in scope.'],'p16ApprovalFailure','1500000 ≤ 1500000 ∧ ¬ Audit.validDana true 1500000 (Audit.expiry + 1) (Audit.expiry + 10) ∧ Audit.p16ValidApproval = false')
add(8,['Receipt selects revision1','Clerical change does not materially alter original requirement'], 'Does R17 retain revision1 despite June3 clerical correction and later commitment?', 'V01 V02 V03 L05', ['V01 keeps earlier accepted requisitions under revision1 for original scope. V02 requires added function or increased consideration for a material amendment.'], ['V03 exact accepted receipt May31 23:59 is one minute before June1 00:00, so revision1 applies.','The contact and cost-center spelling changed, but specification, supplier, price, quantity and function remained unchanged; there is no addition or price increase.','V02 expressly treats such corrections as nonmaterial. Current-version dashboard and June10 commitment do not change governing revision.'],'r17Version','Audit.revisionAt (-1) = 1 ∧ Audit.r17AddedRequirement = false ∧ Audit.r17PriceIncrease = false')
add(9,['R17 exceeds retained threshold','No competition or exception','Director approval does not cure competition failure'], 'Does R17 fail required competition under its retained revision despite director approval?', 'P02 P05 P08 V01 V03 L01 L05', ['Revision1 inclusive threshold is EUR20000. P05/P08 require competition or established exception separately from valid order approval.'], ['R17 remains revision1 and costs EUR22500, greater than its EUR20000 threshold.','L05 explicitly records no competition certificate and no exception, within L01 complete coverage.','Its June9 director approval before June10 commitment satisfies a different requirement. The compliance conjunction still fails its competition limb.'],'r17CompetitionFailure','Audit.threshold (Audit.revisionAt (-1)) < 2250000 ∧ Audit.competitionSatisfied 1 2250000 false false = false ∧ Audit.compliant (Audit.competitionSatisfied 1 2250000 false false) true = false')
add(10,['Boundary receipt selects revision2','EUR22500 independent amount below threshold','No competition obligation under P02'], 'Does R18 avoid a competition obligation under revision2 at the exact receipt boundary?', 'P02 P03 V01 V04 L05', ['V01 includes exact boundary in revision2. Apply normalized independent requirement value to its EUR25000 threshold.'], ['V04 fixes accepted receipt June1 00:00 exactly, not a rounded earlier timestamp; revision2 applies.','EUR22500 is normalized and no other purchase aggregates or materially amends this requirement.','2250000 cents is less than2500000, so P02 does not require competition. This does not exempt the independent approval requirement, which L05 records as satisfied.'],'r18NoCompetition','Audit.revisionAt 0 = 2 ∧ 2250000 < Audit.threshold (Audit.revisionAt 0) ∧ Audit.competitionSatisfied 2 2250000 false false = true')
add(11,['Confirmed active incident','Declaration strictly before commitment','Review exactly48h timely','Instrument separately grants order approval'], 'Does E19 satisfy all urgent-safety exception conditions and separate order approval?', 'P05 P06 L01 L05 X01 X02', ['P06 requires confirmed active safety incident, specified director declaration before commitment and review from commitment through48h inclusive. Order approval remains separately necessary.'], ['X01 confirms active overheating risk at09:30 and links E19 to its immediate control, not merely delayed research.','EM19 atJune22 09:45 identifies incident, requirement, supplier and amount, and expressly contains both declaration and order approval. Commitment follows at10:00.','Review June24 10:00 is exactly two dates after commitment, 2880 minutes=48 hours, within the inclusive limit.','The model checks declaration-before-commitment and the full interval; source wording independently supplies the dual decisions and director authority.'],'e19Exception','Audit.urgentException true true true Audit.e19Declaration Audit.e19Commitment Audit.e19Review ∧ Audit.e19Review - Audit.e19Commitment = 48 * 60 ∧ Audit.e19Declaration < Audit.e19Commitment')
add(12,['Urgency alone insufficient','Declaration and timely review independently present for E19'], 'Is urgency alone insufficient even though E19 has the additional required facts?', 'P06 L05 X01 X02', ['The exception is a conjunction, not a rule activeIncident→exception. P06 expressly excludes incident-only or urgent-email sufficiency.'], ['P06 adds declaration and review to the active-incident condition.','A model with active incident true but declaration and review absent fails the exception, demonstrating the missing-premise inference.','For actual E19, X02 independently supplies both additional conditions with09:45<10:00 and exactly48h review; the separate checked e19Exception target confirms that finite chronology.'],'urgencyInsufficient','¬ Audit.urgentException true false false Audit.e19Declaration Audit.e19Commitment Audit.e19Review','auxiliary',L+['The countermodel does not deny the actual declaration or review; it concerns urgency-only sufficiency. Actual E19 conditions are sourced separately and checked in C06-C11.'])
add(13,['AnnexQ and final determination missing','Sole certified vendor insufficient','Actual exception unresolved'], 'Does the supplied sole-warranty evidence fail to establish E20 proprietary compatibility under missing AnnexQ?', 'P07 V06 X03 X04 X05', ['P07 reserves governing test and certification treatment to AnnexQ and rejects automatic inference from sole certification. Attachment absence does not make conditions waived or false.'], ['X03 reports only a proposed exception, although a separate director order approval exists; no final AnnexQ determination is supplied.','V06 explicitly says AnnexQ and an adopted interpretation are missing. X05 limits completeness to transferred package, not all possible records.','Sole warranty certification would support a warranty-based only-source test; a physical-interoperability test would differ because the rival passes fit/bench tests. Neither is supplied as the actual governing test.','The auxiliary model checks those divergent hypothetical readings, supporting the report support-gap finding without declaring the real exception false.'],'compatibilityOpen','Audit.onlyCompatible Audit.CompatibilityTest.warranty = true ∧ Audit.onlyCompatible Audit.CompatibilityTest.physical = false','auxiliary',L+['These are illustrative alternative definitions, not a reconstruction of AnnexQ. The actual governing test, required certification and final exception decision remain unavailable.'],'Obtain Annex Q and the applicable final determination; retain uncertainty meanwhile.')
add(14,['Rival bench test not disqualification proof','Function and warranty are distinct predicates','Missing definition governs'], 'Does the rival bench result fail to establish that E20 cannot qualify?', 'P07 V06 X03 X04', ['Different predicates cannot be treated as direct contradiction or substituted for an unspecified governing compatibility criterion.'], ['X04 limits the rival report to mechanical fit and electrical bench behavior, excluding durability and warranty acceptance.','The warranty letter concerns certification only and has not assessed rival warranty eligibility. Thus the two sources address different predicates.','If AnnexQ required sole warranty-certified interchangeability, a bench-functional rival might not defeat exclusivity; if it required physical compatibility, it might. The finite alternative-test model makes that divergence explicit.','Without AnnexQ, neither certain qualification nor certain disqualification follows. The correct report describes failure of disqualification evidence, not actual eligibility.'],'compatibilityOpen','Audit.onlyCompatible Audit.CompatibilityTest.warranty = true ∧ Audit.onlyCompatible Audit.CompatibilityTest.physical = false','auxiliary',L+['No claim is made that either hypothetical reading exhausts possible AnnexQ definitions.'],'Obtain Annex Q and a scoped compatibility assessment before deciding eligibility.')
add(15,['Mara asserts exact10:00 approval','Tomas denies same event','Neither retracted','No supplied resolution or precedence'], 'Do the P21 attestations conflict about one approval event without an authoritative supplied resolution?', 'P08 A01 A02 A03 L01', ['P08 preserves attributed testimony until authorized correction/adjudication; authenticated signatures do not make asserted contents necessarily true. L01 excludes P21 completeness.'], ['Visually reviewed A01 states Mara saw director written approval June27 at10:00 before10:30 commitment. A02 explicitly says that same10:00 event did not occur and no director approval occurred by11:00.','Both concern P21, the same morning and timezone. The model records identical event coordinates with opposite assertion polarity, not unconditional opposite world facts.','A03 stipulates both signatures authentic, neither retracted, and no priority, adjudication, corrected register or original instrument resolves the dispute.','OCR token errors were corrected only through hash-bound reviewed transcriptions; Tomas signed at14:30, which provides no precedence rule. The report accurately describes conflict; actual approval remains unresolved.'],'approvalConflict','Audit.mara.order = Audit.tomas.order ∧ Audit.mara.dateOffset = Audit.tomas.dateOffset ∧ Audit.mara.approvalMinute = Audit.tomas.approvalMinute ∧ Audit.mara.asserted ≠ Audit.tomas.asserted ∧ Audit.mara.retracted = false ∧ Audit.tomas.retracted = false',limits=L+['The meta-claim of conflicting evidence is supported. The approval event itself has opposing testimony and is not settled by signature authenticity or the later statement.'])
add(16,['Invoice and delivery prove neither payment nor nonpayment','Missing reconciliation prevents settlement conclusion'], 'Do P21 invoice and delivery records leave payment unresolved?', 'P01 A04 F03 L01', ['P01 separates invoice, acceptance, commitment and payment; no automatic event implication. L01 excludes payment-event completeness.'], ['F03 supplies invoice requesting EUR8000 and acceptance confirming arrival; neither states payment. A04 supplies no bank/payment entry.','Finance explicitly cannot confirm or deny settlement without missing June27-30 bank reconciliation.','The auxiliary model holds invoice and delivery true while allowing paid=true or paid=false. This is a non-entailment witness, not an actual payment decision.','Resolving P21 approval disagreement would still not supply the missing settlement event.'],'paymentOpen','∀ paid : Bool, ∃ w : Audit.PaymentWorld, w.invoice = true ∧ w.delivery = true ∧ w.paid = paid','auxiliary',L+['Payment and nonpayment remain undetermined. The model does not claim that either happened; it isolates absent linkage evidence.'],'Obtain the bank reconciliation and settlement record before deciding payment.')
add(17,['Aggregate competition failure P11/P12','Retained competition failure R17','Invalid approval P16'], 'Are all three named objective compliance failures established within complete coverage?', 'P02 P03 P05 P08 V01 V03 L01 L02 L04 L05 D01 D02', ['P08 compliance requires applicable competition/exception and valid precommitment approval. L01 permits explicit-none event absence only for named covered entries.'], ['P11/P12 known aggregate equals revision2 threshold and lacks recorded competition/exception; director approval cannot cure it.','R17 retained revision1 value exceeds threshold and lacks competition/exception despite director approval.','P16 is below competition threshold but Dana approved after expiry and complete coverage excludes alternatives.','Each witness satisfies the domain and fails a specified compliance limb. The checked conjunction proves all three finite failures without generalizing to E20, P21 or payments.'],'objectiveFailures','Audit.compliant (Audit.competitionSatisfied 2 Audit.rackTotal false false) true = false ∧ Audit.compliant (Audit.competitionSatisfied 1 2250000 false false) true = false ∧ Audit.compliant (Audit.competitionSatisfied 2 1500000 false false) false = false')
add(18,['Management opinion attributed','No standard metric for adjectives','No formal evaluation of merits'], 'Does the report accurately identify the management description as opinion without a supplied formal metric?', 'P08 F05', ['P08 expressly supplies no metric for prudent or commercially elegant; formal compliance calculations do not entail those judgments.'], ['F05 attributes the words to an internal management retrospective, with no decision model, utility scale, benchmark or definition.','P08 explicitly separates such judgments from objective compliance.','The report accurately characterizes that source and limitation. Its qualified meta-claim is supported; the underlying aesthetic/prudential merits are nonformal and receive no Lean target.'],None,None,'not_attempted',L+['No truth value is assigned to the underlying prudence or commercial-elegance opinion.'],'Retain attribution; define an evaluative framework and relevant evidence if management wants those adjectives assessed.')
(p/'findings.json').write_text(json.dumps(findings,indent=2)+'\n')
